  function decodeMccCode(codeStr) {
    const clean = (codeStr || "").trim();
    if (UNIVERSAL_MCC_DICTIONARY[clean]) {
      return UNIVERSAL_MCC_DICTIONARY[clean];
    }
    const num = parseInt(clean, 10);
    if (num >= 3000 && num <= 3299) {
      return { title: "Прямой MCC-код авиакомпании (диапазон 3000–3299)", category: "Авиа билеты / Путешествия" };
    }
    if (num >= 3351 && num <= 3441) {
      return { title: "Прямой MCC-код агентства проката автомобилей (диапазон 3351–3441)", category: "Каршеринг / Аренда авто" };
    }
    if (num >= 3501 && num <= 3839) {
      return { title: "Прямой MCC-код гостиничной сети или отеля (диапазон 3501–3839)", category: "Путешествия / Отели" };
    }
    return null;
  }

