  function resolveCanonicalBankId(bankId, bankName) {
    if (bankId && BANK_BRAND_STYLES[bankId]) return bankId;
    const raw = ((bankId || '') + ' ' + (bankName || '')).toLowerCase();
    if (raw.indexOf('альфа-бизнес') !== -1 || raw.indexOf('alfabiz') !== -1 || raw.indexOf('alfabusiness') !== -1) return 'alfabusiness';
    if (raw.indexOf('альфа') !== -1 || raw.indexOf('alfa') !== -1) return 'alfabank';
    if (raw.indexOf('т-банк') !== -1 || raw.indexOf('тинькофф') !== -1 || raw.indexOf('tbank') !== -1) return 'tbank';
    if (raw.indexOf('сбер') !== -1 || raw.indexOf('sber') !== -1) return 'sber';
    if (raw.indexOf('втб') !== -1 || raw.indexOf('vtb') !== -1) return 'vtb';
    if (raw.indexOf('ozon') !== -1 || raw.indexOf('озон') !== -1) return 'ozon';
    if (raw.indexOf('яндекс') !== -1 || raw.indexOf('yandex') !== -1) return 'yandexpay';
    if (raw.indexOf('совком') !== -1 || raw.indexOf('халва') !== -1 || raw.indexOf('halva') !== -1 || raw.indexOf('sovcom') !== -1) return 'sovcombank';
    if (raw.indexOf('мтс') !== -1 || raw.indexOf('mts') !== -1) return 'mtsdengi';
    if (raw.indexOf('инго') !== -1 || raw.indexOf('ingos') !== -1) return 'ingosstrakh';
    if (raw.indexOf('убрир') !== -1 || raw.indexOf('ubrir') !== -1) return 'ubrir';
    if (raw.indexOf('псб') !== -1 || raw.indexOf('psb') !== -1) return 'psb';
    if (raw.indexOf('отп') !== -1 || raw.indexOf('otp') !== -1) return 'otp';
    if (raw.indexOf('мкб') !== -1 || raw.indexOf('mkb') !== -1) return 'mkb';
    if (raw.indexOf('кеб') !== -1 || raw.indexOf('keb') !== -1 || raw.indexOf('кредит европа') !== -1) return 'keb';
    if (raw.indexOf('юmoney') !== -1 || raw.indexOf('юмани') !== -1 || raw.indexOf('yoomoney') !== -1) return 'yoomoney';
    if (raw.indexOf('wb') !== -1 || raw.indexOf('вайлдберриз') !== -1) return 'wbbank';
    if (raw.indexOf('бспб') !== -1 || raw.indexOf('санкт-петербург') !== -1 || raw.indexOf('ярко') !== -1 || raw.indexOf('ясчитаю') !== -1 || raw.indexOf('bspb') !== -1) return 'bspb';
    return bankId || '';
  }

  function getBankExclusionInfo(bankId, bankName) {
    const canonId = resolveCanonicalBankId(bankId, bankName);
    const ref = state.cardsConfig && state.cardsConfig.banks_mcc_reference && state.cardsConfig.banks_mcc_reference[canonId];
    if (!ref) return { compact: "", list: [], payment: "", payout: "" };
    return {
      compact: ref.excluded_mccs_compact || "",
      list: Array.isArray(ref.excluded_mccs) ? ref.excluded_mccs : [],
      payment: ref.payment_methods || "",
      payout: ref.payout_conversion || ""
    };
  }

  function isMccExcludedInBank(bankId, code4, bankName) {
    const info = getBankExclusionInfo(bankId, bankName);
    return info.list.indexOf(code4) !== -1;
  }

  function getBankBrand(bankId, bankName) {
    const canonId = resolveCanonicalBankId(bankId, bankName);
    if (BANK_BRAND_STYLES[canonId]) return BANK_BRAND_STYLES[canonId];
    return { abbr: (bankName || "Б").slice(0, 2).toUpperCase(), bg: "linear-gradient(135deg, #334155, #475569)", color: "#38bdf8", tint: "rgba(56, 189, 248, 0.05)" };
  }

  // Форматирование одного или нескольких номеров карт одного банка (напр. "4581, 9023" -> "4581 · 9023")
  function formatCardNumbersDisplay(last4Raw) {
    if (!last4Raw) return '0000';
    if (Array.isArray(last4Raw)) {
      const cleanArr = last4Raw.map(function (s) { return String(s).trim(); }).filter(Boolean);
      return cleanArr.length > 0 ? cleanArr.join(' · ') : '0000';
    }
    const parts = String(last4Raw).split(/[,;/]+/).map(function (s) { return s.trim(); }).filter(Boolean);
    return parts.length > 0 ? parts.join(' · ') : '0000';
  }

  // Вариант 3: Компактные квадратные чипы [Д] и [С] с поддержкой нескольких карт у одного банка
  function renderOwnerChip(owner, last4) {
    if (owner === 'Денис / Саша') {
      return '<span class="owner-badge">Денис / Саша</span>';
    }
    const isDenis = owner === 'Денис';
    const formattedL4 = formatCardNumbersDisplay(last4);
    return (
      '<span class="chip-owner-wrap">' +
        '<span class="' + (isDenis ? 'chip-icon-d' : 'chip-icon-s') + '">' + (isDenis ? 'Д' : 'С') + '</span>' +
        '<span class="chip-owner-text">' + owner + '</span>' +
        '<span class="chip-last4-text">• ' + formattedL4 + '</span>' +
      '</span>'
    );
  }

  const BANK_MINI_ICONS = {"alfabank": "data:image/png;base64,", "alfabusiness": "data:image/png;base64,", "tbank": "data:image/png;base64,", "sber": "data:image/png;base64,", "vtb": "data:image/png;base64,", "ozon": "data:image/png;base64,", "yandexpay": "data:image/png;base64,", "sovcombank": "data:image/png;base64,", "mtsdengi": "data:image/png;base64,", "ingosstrakh": "data:image/png;base64,", "ubrir": "data:image/png;base64,", "psb": "data:image/png;base64,", "otp": "data:image/png;base64,", "mkb": "data:image/png;base64,", "keb": "data:image/png;base64,", "yoomoney": "data:image/png;base64,", "wbbank": "data:image/png;base64,", "bspb": "data:image/png;base64,"};

  function renderBankLogoBadge(bankId, bankName) {
    const canonId = resolveCanonicalBankId(bankId, bankName);
    if (BANK_MINI_ICONS[canonId]) {
      return '<img class="bank-logo-img" src="' + BANK_MINI_ICONS[canonId] + '" alt="" loading="lazy">';
    }
    const br = getBankBrand(bankId, bankName);
    const txtCol = br.textColor || "#ffffff";
    const fSize = br.abbr.length >= 4 ? "0.58rem" : (br.abbr.length === 3 ? "0.64rem" : "0.78rem");
    return '<span class="bank-logo-badge" style="background:' + br.bg + '; color:' + txtCol + '; font-size:' + fSize + ';">' + br.abbr + '</span>';
  }

